// Literal callback and label columns retain addresses in the older build; these targets have no allocation or reader in the five current builds. Real allocated targets retain their symbols.
/* Older build's option mask row: the word and label it names are older-build symbols. */
struct MenuLeftoverOptionBitRow {
    void *word;
    void *name;
    unsigned int mask;
    unsigned int enable;
};

/* Older build's menu tuning block (counts, camera offsets and a step angle); fields unnamed. */
struct MenuLeftoverTuning {
    unsigned int word0;
    unsigned int word1;
    unsigned int word2;
    unsigned int word3;
    float originX;
    float originY;
    float scale[3];
    unsigned int count0;
    unsigned int count1;
    float stepAngle;
};

